3D poster card showcase, cards always rocking, crossfade transitions. 16s, 1920x1080, SILENT. CRITICAL ARCHITECTURE: separate the rocking motion from GSAP entirely. Use a TWO-LAYER structure per card: outer .stage controls opacity/scale via GSAP; inner .rocker does the 3D rocking via pure CSS animation on transform only. GSAP must NEVER touch transform on .rocker — only opacity and scale on .stage. This guarantees continuous rock during entry, hold, and exit
```html
<!DOCTYPE html>
<html>
<head>
<meta charset="UTF-8">
<link href="https://fonts.googleapis.com/css2?family=Playfair+Display:wght@700&display=swap" rel="stylesheet">
<style>
*{margin:0;padding:0;box-sizing:border-box;}
body,#scene{width:1920px;height:1080px;overflow:hidden;background:#000;}
#scene{position:relative;display:flex;align-items:center;justify-content:center;}
bg-panel{position:absolute;inset:0;opacity:0;}
#bg1{background:radial-gradient(ellipse at 50% 40%,#3a2800,#1a1000 55%,#080500);}
#bg2{background:radial-gradient(ellipse at 50% 40%,#001435,#000a22 55%,#000308);}
#bg3{background:radial-gradient(ellipse at 50% 40%,#2a0008,#180005 55%,#080002);}
glow-disk{
position:absolute;width:720px;height:960px
border-radius:50%;filter:blur(110px);opacity:0;z-index:1
}
/* OUTER STAGE — GSAP controls opacity only, NO transform */
stage{
position:absolute;z-index:5
display:flex;align-items:center;justify-content:center
width:100%;height:100%
visibility:hidden;opacity:0
}
/* INNER ROCKER — pure CSS 3D rock, GSAP never touches this element */
rocker{
width:580px;height:870px
flex-shrink:0
position:relative;z-index:2
/* perspective in transform for compatibility */
animation:rock 2.5s ease-in-out infinite alternate
/* will-change only transform so GSAP opacity on parent doesn't interfere */
will-change:transform
}
@keyframes rock{
0%  {transform:perspective(1100px) rotateX(4deg)  rotateY(-18deg);}
50% {transform:perspective(1100px) rotateX(2.5deg) rotateY(0deg);}
100%{transform:perspective(1100px) rotateX(4deg)  rotateY(18deg);}
}
card-face{
width:100%;height:100%;border-radius:10px;overflow:hidden;position:relative
}
card-face img{
width:100%;height:100%;object-fit:cover;object-position:center top;display:block
}
card-face::after{
content:"";position:absolute;top:0;left:-70%;width:42%;height:100%
background:linear-gradient(108deg,transparent 28%,rgba(255,255,255,.14) 50%,transparent 72%)
animation:spec 2.4s ease-in-out infinite alternate;pointer-events:none;z-index:2
}
@keyframes spec{from{left:-70%;}to{left:120%;}}
#s1 .card-face{animation:gA 1.8s ease-in-out infinite alternate;}
@keyframes gA{
from{box-shadow:0 0 20px 4px rgba(255,160,20,.28),0 0 60px 8px rgba(255,130,0,.14),0 30px 80px rgba(0,0,0,.88);}
to  {box-shadow:0 0 55px 14px rgba(255,200,60,.62),0 0 130px 28px rgba(255,160,30,.44),0 30px 80px rgba(0,0,0,.88);}
}
#s1 .glow-disk{background:radial-gradient(ellipse,rgba(255,140,20,.50),transparent 70%);}
#s2 .card-face{animation:gB 1.8s ease-in-out infinite alternate;}
@keyframes gB{
from{box-shadow:0 0 20px 4px rgba(40,120,255,.28),0 0 60px 8px rgba(20,90,240,.14),0 30px 80px rgba(0,0,0,.88);}
to  {box-shadow:0 0 55px 14px rgba(80,170,255,.62),0 0 130px 28px rgba(50,130,255,.44),0 30px 80px rgba(0,0,0,.88);}
}
#s2 .glow-disk{background:radial-gradient(ellipse,rgba(30,100,255,.46),transparent 70%);}
#s3 .card-face{animation:gC 1.8s ease-in-out infinite alternate;}
@keyframes gC{
from{box-shadow:0 0 20px 4px rgba(200,30,30,.28),0 0 60px 8px rgba(170,10,10,.14),0 30px 80px rgba(0,0,0,.88);}
to  {box-shadow:0 0 55px 14px rgba(255,60,60,.62),0 0 130px 28px rgba(220,30,30,.44),0 30px 80px rgba(0,0,0,.88);}
}
#s3 .glow-disk{background:radial-gradient(ellipse,rgba(180,20,20,.46),transparent 70%);}
role-label{
position:absolute;top:72px;right:88px;z-index:20
text-align:right;opacity:0
}
role-name{
font-family:'Playfair Display',Georgia,serif
font-size:52px;font-weight:700;color:#f0ece4
line-height:.90;letter-spacing:-.01em
text-shadow:0 2px 20px rgba(0,0,0,.70)
}
#open-fade,#close-fade{
position:absolute;inset:0;z-index:50;background:#000;pointer-events:none
}
#open-fade{opacity:1;}#close-fade{opacity:0;}
</style>
</head>
<body>
<div id="scene">
<div id="bg1" class="bg-panel"></div>
<div id="bg2" class="bg-panel"></div>
<div id="bg3" class="bg-panel"></div>
<div id="open-fade"></div>
<div id="close-fade"></div>
<div class="stage" id="s1">
<div class="glow-disk"></div>
<div class="rocker"><div class="card-face"><img src="{{p1}}" alt=""></div></div>
<div class="role-label" id="l1"><div class="role-name">Alan Turing</div></div>
</div>
<div class="stage" id="s2">
<div class="glow-disk"></div>
<div class="rocker"><div class="card-face"><img src="{{p2}}" alt=""></div></div>
<div class="role-label" id="l2"><div class="role-name">Sherlock Holmes</div></div>
</div>
<div class="stage" id="s3">
<div class="glow-disk"></div>
<div class="rocker"><div class="card-face"><img src="{{p3}}" alt=""></div></div>
<div class="role-label" id="l3"><div class="role-name">Hamlet</div></div>
</div>
</div>
<script src="vendor/gsap.min.js"></script>
<script>
window.addEventListener('DOMContentLoaded',function(){
It NEVER touches .rocker — CSS handles all 3D transform */
var tl=gsap.timeline()
tl.to('#open-fade',{opacity:0,duration:0.4,ease:'power2.out'},0.0)
/* ── CARD 1 IN ── */
tl.to('#bg1',{opacity:1,duration:0.5,ease:'power2.out'},0.3)
tl.set('#s1',{visibility:'visible'},0.35)
tl.to('#s1',{opacity:1,duration:0.5,ease:'power2.out'},0.35)
tl.to('#s1 .glow-disk',{opacity:1,duration:0.5},0.35)
tl.to('#l1',{opacity:1,duration:0.4,ease:'power2.out'},0.75)
/* ── CROSSFADE 1→2 ── */
tl.to('#l1',{opacity:0,duration:0.4},4.3)
tl.to('#bg1',{opacity:0,duration:0.6},4.4)
tl.to('#bg2',{opacity:1,duration:0.6,ease:'power2.inOut'},4.4)
tl.set('#s2',{visibility:'visible'},4.4)
tl.to('#s2',{opacity:1,duration:0.55,ease:'power2.out'},4.4)
tl.to('#s2 .glow-disk',{opacity:1,duration:0.5},4.4)
tl.to('#s1 .glow-disk',{opacity:0,duration:0.45},4.45)
tl.to('#s1',{opacity:0,duration:0.5,ease:'power2.in'
onComplete:function(){gsap.set('#s1',{visibility:'hidden'});}},4.5)
tl.to('#l2',{opacity:1,duration:0.4,ease:'power2.out'},4.85)
/* ── CROSSFADE 2→3 ── */
tl.to('#l2',{opacity:0,duration:0.4},9.3)
tl.to('#bg2',{opacity:0,duration:0.6},9.4)
tl.to('#bg3',{opacity:1,duration:0.6,ease:'power2.inOut'},9.4)
tl.set('#s3',{visibility:'visible'},9.4)
tl.to('#s3',{opacity:1,duration:0.55,ease:'power2.out'},9.4)
tl.to('#s3 .glow-disk',{opacity:1,duration:0.5},9.4)
tl.to('#s2 .glow-disk',{opacity:0,duration:0.45},9.45)
tl.to('#s2',{opacity:0,duration:0.5,ease:'power2.in'
onComplete:function(){gsap.set('#s2',{visibility:'hidden'});}},9.5)
tl.to('#l3',{opacity:1,duration:0.4,ease:'power2.out'},9.85)
/* ── CARD 3 OUT ── */
tl.to(['#l3','#s3 .glow-disk'],{opacity:0,duration:0.4},14.5)
tl.to('#bg3',{opacity:0,duration:0.4},14.5)
tl.to('#s3',{opacity:0,duration:0.5,ease:'power2.in'},14.5)
/* CLOSE */
tl.to('#close-fade',{opacity:1,duration:0.6,ease:'power2.inOut'},14.65)
tl.set('#close-fade',{opacity:1},15.35)
})
</script>
</body>
</html>
